  "mutableContext": [
    {
      "path": "F:/Projects/Chnobel/steuerung/STATUS.md",
      "sha256Before": "586ede4b62484d74740f01b6df9ff428349abc88a131d8bd4932bedd297b3a66",
      "sha256After": "7d455478fad29f8dfe4ca67725a892f9bf72a84b9570c335d04cb12fdc629a1c",
      "bytesBefore": 19645,
